    dateFormat: function(date, flg) {
        if(date == undefined || date =="" || date ==null) return "";

        if(flg == 'date'){

            return date.substring(0,4) +"-"+ date.substring(4,6) +"-" +  date.substring(6,8);
        }else{
            return date.substring(0,2) +":"+ date.substring(2,4);

        }

    },

